(function($) {
	//jquery edges scroll
    $.fn.setEdgesAutoScrollable = function(options) {
        var defaults = {
            scrollspeed: 200,
            incrementSeed: 2
        };
		var me = $(this);
		
		if(options == 'disable'){
			me.parent().unbind('mousemove');
		}else{
			var options = $.extend(defaults, options);
			var top = me.offset().top;
			var bottom = me.height() + top;
			
			me.parent().mousemove(function(e){
				if (e.pageY > top && e.pageY < (top + 30)) {
					me.animate({'scrollTop' : '-=' + ((30 + top - e.pageY) * options.incrementSeed) + 'px'}, options.scrollspeed);
				} else if (e.pageY > (bottom - 30) && e.pageY < bottom) {
					me.animate({'scrollTop' : '+=' + ((30 - bottom + e.pageY ) * options.incrementSeed) + 'px'}, options.scrollspeed);
				} else {
					me.stop();
				}
				return true;
			});
		}
		
		return this;
    };

	//jquery scrollTable
	$.fn.scrollTable = function(height,bottom){
		height = typeof height == 'function'? height() : height;
		tob = bottom || false;
		if($(this).height() < height) return this;
		var t = $(this).wrap('<div class="scrollTable_wrap">').data('hfc', false);
		var mh = $('thead', t).height() + $('tfoot', t).height() + 50;
		height = Math.max(height, mh);
		var w = t.parent().css('height', height);
		
		var initHfc = function(force){
			if(t.data('hfc') && force !== true) return;
			var cw = t.width();
			if(t.data('hfc')){
				var h = w.next('.scrollTable_header').css({'width': cw});
				var f = h.next('.scrollTable_footer').css({'width': cw});
			}else{
				var h = t.clone().attr('id','');
				h.find('tbody, tfoot').remove();
				var f = t.clone().attr('id','');
				f.find('thead, tbody').remove();
				w.after(f).after(h);
				h.wrap('<div class="scrollTable_header">').parent().css({'width': cw,'margin-top': -height});
				f.wrap('<div class="scrollTable_footer">').parent().css({'width': cw,'margin-top': -f.height()});
				t.data('hfc', true);
				$(window).resize(function(){ initHfc(true); });
			}
			hc = $('thead tr:first', h).find('th, td').attr('id', '');
			fc = $('tfoot tr:first', f).find('th, td').attr('id', '');
			$('thead tr:first', t).find('th, td').each(function(i){
				var w = $(this).width();
				if(hc[i]) $(hc[i]).width(w);
				if(fc[i]) $(fc[i]).width(w);
			});
		}
		if(tob) w.scrollTop(t.height() - height);
		w.off('scroll').on('scroll', initHfc).trigger('scroll');
		
		return this;
	};

	//jquery lockForm
	$.fn.lockForm = function(){
		var e = this;
		$('div.row', this).addClass('locked');
		$('input[type=text]:visible, input[type=number]:visible, textarea:visible', this).not('.nolock').each(function(){
			$(this).replaceWith('<span class="locked-field">'+$(this).val()+'</span>');
		});
		$('select:visible', this).not('.nolock').each(function(){
			var v = $(this).data('ov') || $(this).find('option[selected]').html() || '';
			$(this).replaceWith('<span class="locked-field">'+v+'</span>');
		});
		$('input[type=checkbox]:visible, input[type=radio]:visible', this).not('.nolock').each(function(){
			var l = $(e).find('label[for='+$(this).attr('id')+']');
			if($(this).attr('checked')){
				$(this).parent().html('<span class="locked-field">'+l.html()+'</span>');
			}
		});
		$('input[type=hidden], input:hidden', this).remove();
		return this;
	};
	
	//Tree Table
	$.fn.treeTable = function(o){
		var defaults = {'collapse' : true, 'toggler' : 'td:first-child', 'pad' : '&nbsp; &nbsp; '};
		var options = $.extend(defaults, o);
		var c = c || true;
		var tog = {};
		var tbl = this;
		$('tbody tr', this).each(function(i){
			var pid = $(this).data('pid');
			var lv = $(this).data('lv');
			var pad = $('<span class="tpad"></span>');
			$(this).find(options.toggler).prepend(pad);
			if(pid == 0) return;
			if(!tog[pid]) tog[pid] = [];
			tog[pid].push(this);
			while(lv-- > 0){
				pad.append(options.pad);
			}
		});

		$('tbody tr', this).on('click', options.toggler, function(){
			var tr = $(this).parents('tr');
			if(tr.data('collapse')){
				$(tr.data('children')).show();
				tr.data('collapse', false).find('span.ttog').text('▼ ');
			}else{
				$(tr.data('children')).hide();
				tr.data('collapse', true).find('span.ttog').text('► ');
			}
		});

		for(pid in tog){
			tr = $($('tbody tr', this)[pid-1]).data({'collapse': !options.collapse, 'children': tog[pid]});
			tr.find('span.tpad').after('<span class="ttog">'+(options.collapse? '► ' : '')+'</span>');
			if(options.collapse) $(tog[pid]).hide();
		}

		return this;
	};
})(jQuery);

// additional validator methods
jQuery.validator.addMethod('money', function(value, element){
	return this.optional(element) || value.replace(/[\$,]/, '').match(/\d+\.?\d*/);
}, 'Please enter a valid value');

// money format for string
String.prototype.formatMoney = function(c, d, t, p){
    var n = parseFloat(this), c = isNaN(c = Math.abs(c)) ? 2 : c, d = d == undefined ? "." : d, t = t == undefined ? "," : t, s = n < 0 ? "-" : "",
    i = parseInt(n = Math.abs(+n || 0).toFixed(c)) + "", j = (j = i.length) > 3 ? j % 3 : 0;
    return (p||'$') + s + (j ? i.substr(0, j) + t : "") + i.substr(j).replace(/(\d{3})(?=\d)/g, "$1" + t)
    + (c ? d + Math.abs(n - i).toFixed(c).slice(2) : "");
};
